from datetime import datetime
from pathlib import Path
import sqlite3

import flask

import calendar_export
import config
import database
import public_api_data
import starter_catalogue
import uniclubs_database


def _open_connection():
    """Give every request its own short-lived SQLite connection, including health checks."""
    settings = flask.current_app.config
    flask.g.connection = database.get_connection(settings['DATABASE'], uri=settings['DATABASE_URI'])
    if database.has_training_archive(flask.g.connection):
        return flask.jsonify({'error': 'Use the prepared application catalogue.'}), 503
    flask.g.catalogue_id = database.get_catalogue_id(flask.g.connection)
    expected = flask.request.headers.get(config.API_CATALOGUE_HEADER)
    if expected is not None and expected != flask.g.catalogue_id:
        return flask.jsonify({'error': 'The API uses a different activity catalogue.'}), 409
    if (flask.request.method == 'POST' and database.is_reviewed_catalogue(flask.g.connection)
            and expected is None):
        return flask.jsonify({'error': 'Supply the activity catalogue identity for writes.'}), 409


def _catalogue_response(response):
    """Expose a non-secret catalogue identifier while keeping the existing JSON document shape."""
    catalogue_id = flask.g.get('catalogue_id')
    if catalogue_id is not None:
        response.headers[config.API_CATALOGUE_HEADER] = catalogue_id
    return response


def _close_connection(error=None):
    """Close request resources after success, rejected input or an exception."""
    connection = flask.g.pop('connection', None)
    if connection is not None:
        connection.close()


def _invalid_input(error):
    """Return a domain validation message as JSON with HTTP 400."""
    return flask.jsonify({'error': str(error)}), 400


def _database_unavailable(error):
    """Report a temporary storage failure without disclosing filesystem or SQL details."""
    return flask.jsonify({'error': 'Database unavailable. Start WeekWise and try again.'}), 503


def _http_error(error):
    """Keep framework errors, such as an unknown route or method, in the JSON contract."""
    return flask.jsonify({'error': error.name}), error.code


def _date_range(arguments):
    """Parse strict ISO dates and enforce an increasing, bounded half-open query interval."""
    values = []
    for key in ('from', 'to'):
        text = arguments.get(key, '')
        try:
            value = datetime.strptime(text, config.API_DATE_FORMAT)
        except ValueError as error:
            raise ValueError('Supply from and to dates in YYYY-MM-DD format.') from error
        if value.date().isoformat() != text:
            raise ValueError('Supply from and to dates in YYYY-MM-DD format.')
        values.append(value)
    start, end = values
    if not 0 < (end - start).days <= config.MAX_API_RANGE_DAYS:
        raise ValueError(f'Date range must cover 1–{config.MAX_API_RANGE_DAYS} days.')
    return start, end


def _category_document(connection):
    """Group public bundle rows under their direction names and shared palette colours."""
    directions = {}
    frame = database.get_categories_df(connection)
    for row in frame.reset_index().to_dict('records'):
        key = row['direction_key']
        if key not in directions:
            directions[key] = {'key': key, 'name': row['direction_name'],
                               'colors': config.DIRECTION_COLORS[key], 'bundles': []}
        directions[key]['bundles'].append({'id': row['id'], 'key': row['bundle_key'],
                                           'name': row['bundle_name']})
    return {'directions': list(directions.values())}


def _interaction_body():
    """Accept only the specified JSON fields, leaving transition rules in database.py."""
    body = flask.request.get_json(silent=True)
    required = {'user_id', 'event_id', 'action'}
    if (not isinstance(body, dict) or not required.issubset(body)
            or not set(body).issubset(required | {'rating'})):
        raise ValueError('Supply user_id, event_id, action and an optional rating as JSON.')
    database.validate_interaction_input(body['user_id'], body['event_id'],
                                         body['action'], body.get('rating'))
    return body


def create_app(db_file=config.DB_FILE, uri=False):
    """Create the local API; optional SQLite URI mode supports isolated in-memory tests.

    :param db_file: same SQLite file used by Streamlit, or a test-only shared memory URI
    :param uri: enable SQLite URI interpretation for the supplied database name
    :return: configured Flask application; importing this module starts no server
    """
    application = flask.Flask(__name__)
    application.config.update(DATABASE=db_file, DATABASE_URI=uri)
    application.before_request(_open_connection)
    application.after_request(_catalogue_response)
    application.teardown_request(_close_connection)
    application.register_error_handler(ValueError, _invalid_input)
    application.register_error_handler(sqlite3.Error, _database_unavailable)
    for status in (404, 405, 500):
        application.register_error_handler(status, _http_error)

    # Course: L06, A06 – routes map HTTP verbs and URIs to small functions returning JSON.
    @application.get('/health')
    def health():
        """Report the application's protocol version without returning profile data."""
        return flask.jsonify({'status': 'ok', 'version': config.APP_VERSION})

    @application.get('/categories')
    def categories():
        """List directions and their bundles, including both configured colour palettes."""
        return flask.jsonify(_category_document(flask.g.connection))

    @application.get('/events')
    def events():
        """Return public event rows in the requested interval with optional AND filters."""
        start, end = _date_range(flask.request.args)
        rows = database.get_event_records(flask.g.connection, start, end)
        for argument, field in config.API_EVENT_FILTERS.items():
            value = flask.request.args.get(argument)
            if value is not None:
                rows = [row for row in rows if row[field] == value]
        return flask.jsonify(rows)

    @application.get('/events/<int:event_id>')
    def event(event_id):
        """Return one complete occurrence, or HTTP 404 for an unknown ID."""
        row = None
        if 0 < event_id <= config.API_MAX_ID:
            row = database.get_event_row(flask.g.connection, event_id)
        if row is None:
            return flask.jsonify({'error': 'Event was not found.'}), 404
        return flask.jsonify(row)

    @application.post('/interactions')
    def interaction():
        """Delegate one validated action to the shared state machine and return the stored row."""
        body = _interaction_body()
        connection = flask.g.connection
        if not database.user_exists(connection, body['user_id']):
            return flask.jsonify({'error': 'User profile was not found.'}), 404
        if database.get_event_row(connection, body['event_id']) is None:
            return flask.jsonify({'error': 'Event was not found.'}), 404
        result = database.save_interaction(connection, body['user_id'], body['event_id'],
                                            body['action'], body.get('rating'))
        return flask.jsonify(result), 201

    return application


PUBLIC_CLUB_EVENTS_SQL = '''SELECT e.id,e.external_id,e.club_id,e.title,e.start_utc,e.end_utc,
    e.location,e.event_type,e.source_url,e.publication_status,e.availability_state,
    e.requires_membership,e.first_seen_utc,e.last_seen_utc,e.source_missing,
    c.name AS club_name,c.external_id AS club_external_id
    FROM events e JOIN clubs c ON c.id=e.club_id'''
PUBLIC_CLUB_RANGE_SQL = PUBLIC_CLUB_EVENTS_SQL + '''
    WHERE e.start_utc>=? AND e.start_utc<? ORDER BY e.start_utc,e.id'''
PUBLIC_CLUB_EVENT_SQL = PUBLIC_CLUB_EVENTS_SQL + ' WHERE e.id=?'


def _public_read_connection(path):
    """Open a published source read-only; a missing file must not create a new database."""
    return database.get_connection(Path(path).resolve().as_uri() + '?mode=ro', uri=True)


def _public_sport_connection():
    """Reuse one request-local connection to the separately validated public sport file."""
    if 'public_sport' not in flask.g:
        flask.g.public_sport = _public_read_connection(flask.current_app.config['PUBLIC_SPORT'])
    return flask.g.public_sport


def _public_clubs_connection(refresh=None):
    """Refresh a separate public cache before opening its request-local read connection."""
    if 'public_clubs' not in flask.g:
        settings = flask.current_app.config
        try:
            status = public_api_data.ensure_uniclubs(
                settings['PUBLIC_CLUBS'], state=settings['PUBLIC_REFRESH_STATE'],
                refresh=settings['PUBLIC_REFRESH'] if refresh is None else refresh)
        except (ValueError, OSError) as error:
            raise sqlite3.OperationalError('Public source unavailable.') from error
        if not status['available']:
            raise sqlite3.OperationalError('Public source unavailable.')
        flask.g.public_source_status = status
        flask.g.public_clubs = _public_read_connection(settings['PUBLIC_CLUBS'])
    return flask.g.public_clubs


def _close_public_connections(error=None):
    """Release both source files after successful responses and validation failures."""
    for key in ('public_sport', 'public_clubs'):
        connection = flask.g.pop(key, None)
        if connection is not None:
            connection.close()


def _public_response(response):
    """Keep freshness tied to each request rather than an intermediary's cached response."""
    response.headers['Cache-Control'] = 'no-store'
    return response


def _public_storage_error(error):
    """Return a temporary failure without publishing SQL, source files or internal paths."""
    return flask.jsonify({'error': 'The public data source is temporarily unavailable.'}), 503


def _public_utc_boundary(value):
    """Convert a Zurich date boundary through the existing calendar export time boundary."""
    text = calendar_export.format_utc(value)
    utc = datetime.strptime(text, config.ICS_UTC_FORMAT)
    return uniclubs_database.normalize_utc_time(utc.isoformat() + 'Z')


def _public_source_document(refresh=None):
    """Summarize actual SQL rows and data freshness without exposing private application state."""
    sport = _public_sport_connection()
    clubs = _public_clubs_connection(refresh=refresh)
    bounds = database.get_event_date_range(sport)
    sport_dates = [value.isoformat() if value is not None else None for value in bounds]
    return {
        'unisport': {
            'events': sport.execute('SELECT COUNT(*) FROM events').fetchone()[0],
            'courses': sport.execute('SELECT COUNT(*) FROM series').fetchone()[0],
            'first_date': sport_dates[0], 'last_date_inclusive': sport_dates[1],
            'catalogue_id': database.get_catalogue_id(sport),
            'provenance': database.get_provenance_counts(sport), 'automatic_refresh': False,
        },
        'uniclubs': {
            'events': clubs.execute('SELECT COUNT(*) FROM events').fetchone()[0],
            'clubs': clubs.execute('SELECT COUNT(*) FROM clubs').fetchone()[0],
            'automatic_refresh': True, 'refresh': flask.g.public_source_status,
        },
    }


def create_public_app(sport_file=None, clubs_file=None, refresh=True):
    """Create the deployable read-only API without any local profile or interaction routes.

    :param sport_file: published sport starter; startup rejects private or demo databases
    :param clubs_file: separate public cache, refreshed from the validated GitHub event feed
    :param refresh: False uses stored public data without outbound requests, useful for tests
    :return: Flask application; collection ranges use inclusive/exclusive Zurich start dates
    """
    sport_file = config.PUBLIC_UNISPORT_SEED if sport_file is None else sport_file
    clubs_file = config.PUBLIC_API_UNICLUBS_DB if clubs_file is None else clubs_file
    connection = _public_read_connection(sport_file)
    try:
        starter_catalogue.validate_starter(connection)
    finally:
        connection.close()
    application = flask.Flask(__name__)
    application.config.update(PUBLIC_SPORT=sport_file, PUBLIC_CLUBS=clubs_file,
                              PUBLIC_REFRESH=refresh, PUBLIC_REFRESH_STATE={})
    status = public_api_data.ensure_uniclubs(
        clubs_file, state=application.config['PUBLIC_REFRESH_STATE'], refresh=False)
    if not status['available']:
        raise sqlite3.OperationalError('The public club cache could not be initialized.')
    application.after_request(_public_response)
    application.teardown_request(_close_public_connections)
    application.register_error_handler(ValueError, _invalid_input)
    application.register_error_handler(sqlite3.Error, _public_storage_error)
    for status in (404, 405, 500):
        application.register_error_handler(status, _http_error)
    _register_public_routes(application)
    return application


def _register_public_routes(application):
    """Register only bounded public GET queries, preserving the legacy local API separately."""
    @application.get('/')
    def public_index():
        """Describe the API paths and the common local date query contract."""
        return flask.jsonify({
            'name': config.APP_NAME, 'mode': 'public-read-only',
            'time_zone': config.TIMEZONE_NAME, 'maximum_days': config.MAX_API_RANGE_DAYS,
            'date_parameters': {'from': 'inclusive', 'to': 'exclusive'},
            'routes': ['/health', '/sources', '/unisport/events', '/unisport/events/<id>',
                       '/uniclubs/events', '/uniclubs/events/<id>', '/uniclubs/clubs'],
        })

    @application.get('/health')
    def public_health():
        """Verify both SQL sources, including the current fallback or source freshness state."""
        return flask.jsonify({'status': 'ok', 'version': config.APP_VERSION,
                              'mode': 'public-read-only',
                              'sources': _public_source_document(refresh=False)})

    @application.get('/sources')
    def public_sources():
        """Expose aggregate counts and provenance so consumers can assess their data source."""
        return flask.jsonify(_public_source_document())

    @application.get('/unisport/events')
    def public_sport_events():
        """Select sport occurrences whose Zurich start falls inside the bounded interval."""
        start, end = _date_range(flask.request.args)
        return flask.jsonify(database.get_event_records(_public_sport_connection(), start, end))

    @application.get('/unisport/events/<int:event_id>')
    def public_sport_event(event_id):
        """Return one public sport occurrence and its explicit projected or website provenance."""
        row = None
        if 0 < event_id <= config.API_MAX_ID:
            row = database.get_event_row(_public_sport_connection(), event_id)
        return (flask.jsonify(row) if row is not None
                else (flask.jsonify({'error': 'Event was not found.'}), 404))

    @application.get('/uniclubs/events')
    def public_club_events():
        """Select canonical UTC source rows by their corresponding Zurich start dates."""
        start, end = _date_range(flask.request.args)
        params = (_public_utc_boundary(start), _public_utc_boundary(end))
        rows = _public_clubs_connection().execute(PUBLIC_CLUB_RANGE_SQL, params).fetchall()
        return flask.jsonify([dict(row) for row in rows])

    @application.get('/uniclubs/events/<int:event_id>')
    def public_club_event(event_id):
        """Return one stable source event, including nullable end and original status flags."""
        row = None
        if 0 < event_id <= config.API_MAX_ID:
            row = _public_clubs_connection().execute(PUBLIC_CLUB_EVENT_SQL, (event_id,)).fetchone()
        return (flask.jsonify(dict(row)) if row is not None
                else (flask.jsonify({'error': 'Event was not found.'}), 404))

    @application.get('/uniclubs/clubs')
    def public_clubs():
        """Return explicitly selected public club fields without local profile information."""
        rows = _public_clubs_connection().execute('''SELECT id,external_id,name,source_url
            FROM clubs ORDER BY id''').fetchall()
        return flask.jsonify([dict(row) for row in rows])


app = create_app()


def prepare_database(db_file=config.DB_FILE, uri=False):
    """Initialize an empty schema when the API is started before Streamlit, preserving all data."""
    connection = database.get_connection(db_file, uri=uri)
    try:
        database.init_db(connection)
        starter_catalogue.bootstrap_starter(connection)
    finally:
        connection.close()


if __name__ == '__main__':
    prepare_database()
    app.run(host=config.API_HOST, port=config.API_PORT, debug=False,
            use_reloader=False, threaded=False)
